export default JSON.parse(
  "{\n  \"workId\": \"mo-zi\",\n  \"chapter\": {\n    \"id\": \"mo-zi_ch-9\",\n    \"workId\": \"mo-zi\",\n    \"order\": 9,\n    \"title\": \"尚賢中\",\n    \"difficulty\": 5,\n    \"estimatedMinutes\": 12,\n    \"passageIds\": [\n      \"mo-zi_ch-9_p-1\",\n      \"mo-zi_ch-9_p-2\",\n      \"mo-zi_ch-9_p-3\",\n      \"mo-zi_ch-9_p-4\",\n      \"mo-zi_ch-9_p-5\",\n      \"mo-zi_ch-9_p-6\",\n      \"mo-zi_ch-9_p-7\",\n      \"mo-zi_ch-9_p-8\"\n    ],\n    \"tags\": [\n      \"墨家\",\n      \"墨子\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"mo-zi_ch-9_p-1\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子言曰：「今王公大人之君人民，主社稷，治國家，欲脩保而勿失，故不察尚賢為政之本也。何以知尚賢之為政本也？曰自貴且智者，為政乎愚且賤者，則治；自愚且賤者，為政乎貴且智者，則亂。是以知尚賢之為政本也。故古者聖王甚尊尚賢而任使能，不黨父兄，不偏貴富，不嬖顏色，賢者舉而上之，富而貴之，以為官長；不肖者抑而廢之，貧而賤之以為徒役，是以民皆勸其賞，畏其罰，相率而為賢。是以賢者眾，而不肖者寡，此謂進賢。然後聖人聽其言，跡其行，察其所能，而慎予官，此謂事能。故可使治國者，使治國，可使長官者，使長官，可使治邑者，使治邑。凡所使治國家，官府，邑里，此皆國之賢者也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-9_p-1_s-1\",\n        \"mo-zi_ch-9_p-1_s-2\",\n        \"mo-zi_ch-9_p-1_s-3\",\n        \"mo-zi_ch-9_p-1_s-4\",\n        \"mo-zi_ch-9_p-1_s-5\",\n        \"mo-zi_ch-9_p-1_s-6\",\n        \"mo-zi_ch-9_p-1_s-7\",\n        \"mo-zi_ch-9_p-1_s-8\",\n        \"mo-zi_ch-9_p-1_s-9\",\n        \"mo-zi_ch-9_p-1_s-10\",\n        \"mo-zi_ch-9_p-1_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"子墨子說道：今王公大人的君人民，主社稷，治國家，欲脩保而且勿失，所以不察尚賢為政的本啊。何以知尚賢的為政本啊？說道：自貴且智的人，為政乎愚且賤的人，則治；自愚且賤的人，為政乎貴且智的人，則亂。是以知尚賢的為政本啊。所以古代聖王甚尊尚賢而且任使能，不黨父兄，不偏貴富，不嬖顏色，賢的人舉而且上的，富而且貴的，以為官長；不肖的人抑而且廢的，貧而且賤的以為徒役，是以民皆勸他的賞，畏他的罰，相率而且為賢。是以賢的人眾，而且不肖的人寡，此謂進賢。然後聖人聽他的言，跡他的行，察他的所能，而且慎予官，此謂事能。所以可使治國的人，使治國，可使長官的人，使長官，可使治邑的人，使治邑。凡所使治國家，官府，邑里，此皆國的賢的人啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚賢中〉。墨子學派以兼愛天下為宗，開篇「子墨子言曰：「今王公大人之君人民，主社稷，治國家，欲脩保而勿失，故不察尚賢為政之本也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「言」、「今」、「王」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「子墨子言曰今王公大人之君人民主社稷治國家欲脩保而」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「何以知尚賢之為政本也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"order\": 2,\n      \"canonicalText\": \"賢者之治國者也，蚤朝晏退，聽獄治政，是以國家治而刑法正。賢者之長官也，夜寢夙興，收斂關市、山林、澤梁之利，以實官府，是以官府實而財不散。賢者之治邑也，蚤出莫入，耕稼、樹藝、聚菽粟，是以菽粟多而民足乎食。故國家治則刑法正，官府實則萬民富。上有以絜為酒醴粢盛，以祭祀天鬼；外有以為皮幣，與四鄰諸侯交接，內有以食飢息勞，將養其萬民。外有以懷天下之賢人。是故上者天鬼富之，外者諸侯與之，內者萬民親之，賢人歸之，以此謀事則得，舉事則成，入守則固，出誅則彊。故唯昔三代聖王堯、舜、禹、湯、文、武，之所以王天下正諸侯者，此亦其法已。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-9_p-2_s-1\",\n        \"mo-zi_ch-9_p-2_s-2\",\n        \"mo-zi_ch-9_p-2_s-3\",\n        \"mo-zi_ch-9_p-2_s-4\",\n        \"mo-zi_ch-9_p-2_s-5\",\n        \"mo-zi_ch-9_p-2_s-6\",\n        \"mo-zi_ch-9_p-2_s-7\",\n        \"mo-zi_ch-9_p-2_s-8\",\n        \"mo-zi_ch-9_p-2_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"賢的人的治國的人啊，蚤朝晏退，聽獄治政，是以國家治而且刑法正。賢的人的長官啊，夜寢夙興，收斂關市、山林、澤梁的利，以客觀實體官府，是以官府客觀實體而且財不散。賢的人的治邑啊，蚤出莫入，耕稼、樹藝、聚菽粟，是以菽粟多而且民足乎食。所以國家治則刑法正，官府客觀實體則萬民富。上有以絜為酒醴粢盛，以祭祀天鬼；外有以為皮幣，與四鄰諸侯交接，內有以食飢息勞，將養他的萬民。外有以懷天下的賢人。正因為如此上的人天鬼富的，外的人諸侯與的，內的人萬民親的，賢人歸的，以此謀事則得，舉事則成，入守則固，出誅則彊。所以唯昔三代聖王堯、舜、禹、湯、文、武，的所以王天下正諸侯的人，此亦他的法已。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚賢中〉。墨子學派以兼愛天下為宗，開篇「賢者之治國者也，蚤朝晏退，聽獄治政，是以國家治而刑法正」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「賢」、「治」、「國」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「賢者之治國者也蚤朝晏退聽獄治政是以國家治而刑法正」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「賢者之長官也，夜寢夙興，收斂關市、山林、澤梁之利，以實官府，是以官府實而財不散」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"order\": 3,\n      \"canonicalText\": \"既曰若法，未知所以行之術，則事猶若未成，是以必為置三本。何謂三本？曰爵位不高則民不敬也，蓄祿不厚則民不信也，政令不斷則民不畏也。故古聖王高予之爵，重予之祿，任之以事，斷予之令，夫豈為賢臣賜哉，欲其事之成也。《詩》曰：『告女憂卹，誨女予爵，孰能執熱，鮮不用濯。』則此語古者國君諸侯之不可以不執善，承嗣輔佐也。譬之猶執熱之有濯也。將休其手焉。古者聖王唯毋得賢人而使之，般爵以貴之，裂地以封之，終身不厭。賢人唯毋得明君而事之，竭四肢之力以任君之事，終身不倦。若有美善則歸之上，是以美善在上，而所怨謗在下，寧樂在君，憂慼在臣，故古者聖王之為政若此。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-9_p-3_s-1\",\n        \"mo-zi_ch-9_p-3_s-2\",\n        \"mo-zi_ch-9_p-3_s-3\",\n        \"mo-zi_ch-9_p-3_s-4\",\n        \"mo-zi_ch-9_p-3_s-5\",\n        \"mo-zi_ch-9_p-3_s-6\",\n        \"mo-zi_ch-9_p-3_s-7\",\n        \"mo-zi_ch-9_p-3_s-8\",\n        \"mo-zi_ch-9_p-3_s-9\",\n        \"mo-zi_ch-9_p-3_s-10\",\n        \"mo-zi_ch-9_p-3_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"既說道：若法，未知所以行的術，則事猶若未成，是以必為置三本。何謂三本？說道：爵位不高則民不敬啊，蓄祿不厚則民不信啊，政令不斷則民不畏啊。所以古聖王高予的爵，重予的祿，任的以事，斷予的令，夫豈為賢臣賜哉，欲他的事的成啊。《詩》說道：告女憂卹，誨女予爵，孰能執熱，鮮不用濯。則此語古代國君諸侯的不可以不執善，承嗣輔佐啊。譬的猶執熱的有濯啊。將休他的手焉。古代聖王唯毋得賢人而且使的，般爵以貴的，裂地以封的，終身不厭。賢人唯毋得明君而且事的，竭四肢的力以任君的事，終身不倦。若有美善則歸的上，是以美善在上，而且所怨謗在下，寧樂在君，憂慼在臣，所以古代聖王的為政若此。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚賢中〉。墨子學派以兼愛天下為宗，開篇「既曰若法，未知所以行之術，則事猶若未成，是以必為置三本」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「既」、「法」、「未」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「既曰若法未知所以行之術則事猶若未成是以必為置三本」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「何謂三本」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"order\": 4,\n      \"canonicalText\": \"今王公大人亦欲效人以尚賢使能為政，高予之爵，而祿不從也。夫高爵而無祿，民不信也。曰：『此非中實愛我也，假藉而用我也。』夫假藉之民，將豈能親其上哉！故先王言曰：「貪於政者，不能分人以事；厚於貨者，不能分人以祿。」事則不與，祿則不分，請問天下之賢人將何自至乎王公大人之側哉？若苟賢者不至乎王公大人之側，則此不肖者在左右也。不肖者在左右，則其所譽不當賢，而所毀不當暴，王公大人尊此以為政乎國家，則賞亦必不當賢，而罰亦必不當暴。若苟賞不當賢而罰不當暴，則是為賢者不勸而為暴者不沮矣。是以入則不慈孝父母，出則不長弟鄉里，居處無節，出入無度，男女無別。使治官府則盜竊，守城則倍畔，君有難則不死，出亡則不從，使斷獄則不中，分財則不均，與謀事不得，舉事不成，入守不固，出誅不彊。故雖昔者三代暴王桀紂幽厲之所以失措其國家，傾覆其社稷者，已此故也。何則？皆以明小物而不明大物也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-9_p-4_s-1\",\n        \"mo-zi_ch-9_p-4_s-2\",\n        \"mo-zi_ch-9_p-4_s-3\",\n        \"mo-zi_ch-9_p-4_s-4\",\n        \"mo-zi_ch-9_p-4_s-5\",\n        \"mo-zi_ch-9_p-4_s-6\",\n        \"mo-zi_ch-9_p-4_s-7\",\n        \"mo-zi_ch-9_p-4_s-8\",\n        \"mo-zi_ch-9_p-4_s-9\",\n        \"mo-zi_ch-9_p-4_s-10\",\n        \"mo-zi_ch-9_p-4_s-11\",\n        \"mo-zi_ch-9_p-4_s-12\",\n        \"mo-zi_ch-9_p-4_s-13\",\n        \"mo-zi_ch-9_p-4_s-14\",\n        \"mo-zi_ch-9_p-4_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今王公大人亦欲效人以尚賢使能為政，高予的爵，而且祿不從啊。夫高爵而且無祿，民不信啊。說道：此絕不是中客觀實體愛我啊，假藉而且用我啊。夫假藉的民，將豈能親他的上哉！所以先王說道：貪於政的人，不能分人以事；厚於貨的人，不能分人以祿。事則不與，祿則不分，請問天下的賢人將何自至乎王公大人的側哉？若苟賢的人不至乎王公大人的側，則此不肖的人在左右啊。不肖的人在左右，則他的所譽不當賢，而且所毀不當暴，王公大人尊此以為政乎國家，則賞亦必不當賢，而且罰亦必不當暴。若苟賞不當賢而且罰不當暴，則是為賢的人不勸而且為暴的人不沮矣。是以入則不慈孝父母，出則不長弟鄉里，居處無節，出入無度，男女無別。使治官府則盜竊，守城則倍畔，君有難則不死，出亡則不從，使斷獄則不中，分財則不均，與謀事不得，舉事不成，入守不固，出誅不彊。所以雖昔日三代暴王桀紂幽厲的所以失措他的國家，傾覆他的社稷的人，已此所以啊。何則？皆以明小物而且不明大物啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚賢中〉。墨子學派以兼愛天下為宗，開篇「今王公大人亦欲效人以尚賢使能為政，高予之爵，而祿不從也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「王」、「公」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今王公大人亦欲效人以尚賢使能為政高予之爵而祿不從」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「夫高爵而無祿，民不信也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"order\": 5,\n      \"canonicalText\": \"今王公大人，有一衣裳不能制也，必藉良工；有一牛羊不能殺也，必藉良宰。故當若之二物者，王公大人皆知以尚賢使能為政也。逮至其國家之亂，社稷之危，則不知使能以治之，親戚則使之，無故富貴、面目佼好則使之。夫無故富貴、面目佼好則使之，豈必智且有慧哉！若使之治國家，則此使不智慧者治國家也，國家之亂既可得而知已。且夫王公大人有所愛其色而使，其心不察其知而與其愛。是故不能治百人者，使處乎千人之官，不能治千人者，使處乎萬人之官。此其故何也？曰處若官者爵高而祿厚，故愛其色而使之焉。夫不能治千人者，使處乎萬人之官，則此官什倍也。夫治之法將日至者也，日以治之，日不什脩，知以治之，知不什益，而予官什倍，則此治一而棄其九矣。雖日夜相接以治若官，官猶若不治，此其故何也？則王公大人不明乎以尚賢使能為政也。故以尚賢使能為政而治者，若吾言之謂也，以下賢為政而亂者，若吾言之謂也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-9_p-5_s-1\",\n        \"mo-zi_ch-9_p-5_s-2\",\n        \"mo-zi_ch-9_p-5_s-3\",\n        \"mo-zi_ch-9_p-5_s-4\",\n        \"mo-zi_ch-9_p-5_s-5\",\n        \"mo-zi_ch-9_p-5_s-6\",\n        \"mo-zi_ch-9_p-5_s-7\",\n        \"mo-zi_ch-9_p-5_s-8\",\n        \"mo-zi_ch-9_p-5_s-9\",\n        \"mo-zi_ch-9_p-5_s-10\",\n        \"mo-zi_ch-9_p-5_s-11\",\n        \"mo-zi_ch-9_p-5_s-12\",\n        \"mo-zi_ch-9_p-5_s-13\",\n        \"mo-zi_ch-9_p-5_s-14\",\n        \"mo-zi_ch-9_p-5_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今王公大人，有一衣裳不能制啊，必藉良工；有一牛羊不能殺啊，必藉良宰。所以當若的二物的人，王公大人皆知以尚賢使能為政啊。逮至他的國家的亂，社稷的危，則不知使能以治的，親戚則使的，無所以富貴、面目佼好則使的。夫無所以富貴、面目佼好則使的，豈必智且有慧哉！若使的治國家，則此使不智慧的人治國家啊，國家的亂既可得而且知已。再的人況且王公大人有所愛他的色而且使，他的心不察他的知而且與他的愛。正因為如此不能治百人的人，使處乎千人的官，不能治千人的人，使處乎萬人的官。此他的所以何啊？說道：處若官的人爵高而且祿厚，所以愛他的色而且使的焉。夫不能治千人的人，使處乎萬人的官，則此官什倍啊。夫治的法將日至的人啊，日以治的，日不什脩，知以治的，知不什益，而且予官什倍，則此治一而且棄他的九矣。雖日夜相接以治若官，官猶若不治，此他的所以何啊？則王公大人不明乎以尚賢使能為政啊。所以以尚賢使能為政而且治的人，若吾言的謂啊，以下賢為政而且亂的人，若吾言的謂啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚賢中〉。墨子學派以兼愛天下為宗，開篇「今王公大人，有一衣裳不能制也，必藉良工」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「王」、「公」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今王公大人有一衣裳不能制也必藉良工有一牛羊不能殺」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「有一牛羊不能殺也，必藉良宰」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"order\": 6,\n      \"canonicalText\": \"今王公大人中實將欲治其國家，欲脩保而勿失，胡不察尚賢為政之本也？且以尚賢為政之本者，亦豈獨子墨子之言哉！此聖王之道，先王之書距年之言也。傳曰：『求聖君哲人，以裨輔而身』，《湯誓》雲：『聿求元聖，與之戮力同心，以治天下。』則此言聖之不失以尚賢使能為政也。故古者聖王唯能審以尚賢使能為政，無異物雜焉，天下皆得其利。古者舜耕歷山，陶河瀕，漁雷澤，堯得之服澤之陽，舉以為天子，與接天下之政，治天下之民。伊摯，有莘氏女之私臣，親為庖人，湯得之，舉以為己相，與接天下之政，治天下之民。傅說被褐帶索。庸築乎傅巖，武丁得之，舉以為三公，與接天下之政，治天下之民。此何故始賤卒而貴，始貧卒而富？則王公大人明乎以尚賢使能為政。是以民無飢而不得食，寒而不得衣，勞而不得息，亂而不得治者。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-9_p-6_s-1\",\n        \"mo-zi_ch-9_p-6_s-2\",\n        \"mo-zi_ch-9_p-6_s-3\",\n        \"mo-zi_ch-9_p-6_s-4\",\n        \"mo-zi_ch-9_p-6_s-5\",\n        \"mo-zi_ch-9_p-6_s-6\",\n        \"mo-zi_ch-9_p-6_s-7\",\n        \"mo-zi_ch-9_p-6_s-8\",\n        \"mo-zi_ch-9_p-6_s-9\",\n        \"mo-zi_ch-9_p-6_s-10\",\n        \"mo-zi_ch-9_p-6_s-11\",\n        \"mo-zi_ch-9_p-6_s-12\",\n        \"mo-zi_ch-9_p-6_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今王公大人中客觀實體將欲治他的國家，欲脩保而且勿失，胡不察尚賢為政的本啊？且以尚賢為政的本的人，亦豈獨子墨子的言哉！此聖王的道，先王的書距年的言啊。傳說道：求聖君哲人，以裨輔而且身，《湯誓》雲：聿求元聖，與的戮力同心，以治天下。則此言聖的不失以尚賢使能為政啊。所以古代聖王唯能審以尚賢使能為政，無異物雜焉，天下皆得他的利。古代舜耕歷山，陶河瀕，漁雷澤，堯得的服澤的陽，舉以為天子，與接天下的政，治天下的民。伊摯，有莘氏女的私臣，親為庖人，湯得的，舉以為己相，與接天下的政，治天下的民。傅推理說理被褐帶索。庸築乎傅巖，武丁得的，舉以為三公，與接天下的政，治天下的民。此何所以始賤卒而且貴，始貧卒而且富？則王公大人明乎以尚賢使能為政。是以民無飢而且不得食，寒而且不得衣，勞而且不得息，亂而且不得治的人。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚賢中〉。墨子學派以兼愛天下為宗，開篇「今王公大人中實將欲治其國家，欲脩保而勿失，胡不察尚賢為政之本也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「王」、「公」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今王公大人中實將欲治其國家欲脩保而勿失胡不察尚賢」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「且以尚賢為政之本者，亦豈獨子墨子之言哉」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"order\": 7,\n      \"canonicalText\": \"故古聖王以審以尚賢使能為政，而取法於天。雖天亦不辯貧富、貴賤、遠邇、親疏、賢者舉而尚之，不肖者抑而廢之。然則富貴為賢，以得其賞者誰也？曰若昔者三代聖王堯、舜、禹、湯、文、武者是也。所以得其賞何也？曰其為政乎天下也，兼而愛之，從而利之，又率天下之萬民以尚尊天、事鬼、愛利萬民，是故天鬼賞之，立為天子，以為民父母，萬民從而譽之曰『聖王』，至今不已。則此富貴為賢，以得其賞者也。然則富貴為暴，以得其罰者誰也？曰若昔者三代暴王桀、紂、幽、厲者是也。何以知其然也？曰其為政乎天下也，兼而憎之，從而賊之，又率天下之民以詬天侮鬼，賊傲萬民，是故天鬼罰之，使身死而為刑戮，子孫離散，室家喪滅，絕無後嗣，萬民從而非之曰「暴王」，至今不已。則此富貴為暴，而以得其罰者也。然則親而不善，以得其罰者誰也？曰若昔者伯鯀，帝之元子，廢帝之德庸，既乃刑之於羽之郊，乃熱照無有及也，帝亦不愛。則此親而不善以得其罰者也。然則天之所使能者誰也？曰若昔者禹、稷、皋陶是也。何以知其然也？先王之書呂刑道之曰：『皇帝清問下民，有辭有苗。曰群后之肆在下，明明不常，鰥寡不蓋，德威維威，德明維明。乃名三後，恤功於民，伯夷降典，哲民維刑。禹平水土，主名山川。稷隆播種，農殖嘉穀。三後成功，維假於民。』則此言三聖人者，謹其言，慎其行，精其思慮，索天下之隱事遺利，以上事天，則天鄉其德，下施之萬民，萬民被其利，終身無已。故先王之言曰：『此道也，大用之天下則不窕，小用之則不困，脩用之則萬民被其利，終身無已。』周頌道之曰：『聖人之德，若天之高，若地之普，其有昭於天下也。若地之固，若山之承，不坼不崩。若日之光，若月之明，與天地同常。』則此言聖人之德，章明博大，埴固，以脩久也。故聖人之德蓋總乎天地者也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-9_p-7_s-1\",\n        \"mo-zi_ch-9_p-7_s-2\",\n        \"mo-zi_ch-9_p-7_s-3\",\n        \"mo-zi_ch-9_p-7_s-4\",\n        \"mo-zi_ch-9_p-7_s-5\",\n        \"mo-zi_ch-9_p-7_s-6\",\n        \"mo-zi_ch-9_p-7_s-7\",\n        \"mo-zi_ch-9_p-7_s-8\",\n        \"mo-zi_ch-9_p-7_s-9\",\n        \"mo-zi_ch-9_p-7_s-10\",\n        \"mo-zi_ch-9_p-7_s-11\",\n        \"mo-zi_ch-9_p-7_s-12\",\n        \"mo-zi_ch-9_p-7_s-13\",\n        \"mo-zi_ch-9_p-7_s-14\",\n        \"mo-zi_ch-9_p-7_s-15\",\n        \"mo-zi_ch-9_p-7_s-16\",\n        \"mo-zi_ch-9_p-7_s-17\",\n        \"mo-zi_ch-9_p-7_s-18\",\n        \"mo-zi_ch-9_p-7_s-19\",\n        \"mo-zi_ch-9_p-7_s-20\",\n        \"mo-zi_ch-9_p-7_s-21\",\n        \"mo-zi_ch-9_p-7_s-22\",\n        \"mo-zi_ch-9_p-7_s-23\",\n        \"mo-zi_ch-9_p-7_s-24\",\n        \"mo-zi_ch-9_p-7_s-25\",\n        \"mo-zi_ch-9_p-7_s-26\",\n        \"mo-zi_ch-9_p-7_s-27\",\n        \"mo-zi_ch-9_p-7_s-28\",\n        \"mo-zi_ch-9_p-7_s-29\",\n        \"mo-zi_ch-9_p-7_s-30\",\n        \"mo-zi_ch-9_p-7_s-31\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"因此古代聖王審慎地以崇尚賢士、任用能人來治理政事，並以天道作為效法的準則。上天也是不分貧窮富貴、地位貴賤、地域遠近、血緣親疏的，只要是賢能之士就提拔任用，不肖之徒就壓抑廢黜。既然如此，那麼居於富貴之位而實行賢政，因而獲得上天賞賜的是誰呢？就是昔日三代的聖王堯、舜、禹、商湯、周文王與周武王。他們憑藉什麼獲得賞賜呢？因為他們在治理天下政務時，平等博愛萬民，為萬民興利，又率領天下民眾崇敬尊崇上天、事奉鬼神、愛護利益萬民，所以天帝與鬼神降下賞賜，立他們為天子，讓他們作為萬民的父母，萬民也隨之讚頌他們為「聖王」，至今仍讚揚不息。這就是居富貴而行賢政、因而獲得天賞的例證。那麼居於富貴之位而行暴虐、因而遭受上天懲罰的是誰呢？就是昔日三代的暴君夏桀、商紂、周幽王與周厲王。憑何得知是這樣呢？因為他們在治理天下時，普遍憎恨萬民，進而殘害萬民，又率領天下民眾詬罵上天、侮辱鬼神、殘害凌辱萬民，所以天帝與鬼神降罰於他們，使他們身受極刑殺戮，子孫流離失所，家族滅亡，斷絕後嗣，萬民隨之斥責他們為「暴君」，至今仍非議不休。這就是居富貴而行暴虐、因而遭受天罰的例證。那麼與帝王有至親血緣卻品行不善、因而遭受天罰的是誰呢？就是從前的伯鯀，他是天帝的大兒子，卻廢棄了天帝的大德常法，最終被誅殺於羽山的郊野，罪咎昭彰而無人能施救，天帝也絕不姑息偏袒。這就是雖具骨肉至親卻不為善、因而遭受天罰的例證。那麼上天所選拔任用的能臣是誰呢？就是昔日的禹、后稷與皋陶。憑何得知是這樣呢？先王的典籍《呂刑》記載說：『上帝審慎考察天下的百姓，有苗氏發起暴亂而受辭訟控訴。眾諸侯肆行於下位，賞罰不明而失其常軌，鰥寡孤獨無所庇護，天降德威以為懲戒，顯明德澤以作表彰。於是任命三位賢后，為萬民憂勞建功：伯夷頒布禮儀典章，教導啟迪百姓遵守法度；大禹平定水土水患，命名祭奠名山大川；后稷推廣播種農藝，教民栽植優良穀物。三位賢后建立了功業，使萬民均蒙受其福佑。』這段話表明這三位聖者，言論謹慎，行為端正，思慮周密，探求天下隱密的事理與遺漏的利益，對上侍奉天帝，天帝便喜愛其德行；對下施惠萬民，萬民便受其利澤，終生獲益不盡。因此先王的名言說：『這套原則，廣泛施行於天下則不顯狹隘，局限施行於細微則不受困頓，長久踐行則萬民蒙受福祉，終身享用不盡。』《周頌》也稱讚說：『聖人的德澤，如同蒼天之高遠，如同大地之廣闊，光輝照臨於天下。如同大地般穩固，如同群山般承載萬物，永不崩塌開裂；如同太陽的光輝，如同月亮的明潔，與天地永恆長存。』這便是稱頌聖人之德光明博大、根基深厚堅實而歷久不衰。因此聖人的德澤，真正涵蓋並融合了天地的大道。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚賢中〉。墨子學派以兼愛天下為宗，開篇「故古聖王以審以尚賢使能為政，而取法於天」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「古」、「聖」、「王」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「故古聖王以審以尚賢使能為政而取法於天雖天亦不辯貧」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「雖天亦不辯貧富、貴賤、遠邇、親疏、賢者舉而尚之，不肖者抑而廢之」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"order\": 8,\n      \"canonicalText\": \"今王公大人慾王天下，正諸侯，夫無德義將何以哉？其說將必挾震威彊。今王公大人將焉取挾震威彊哉？傾者民之死也。民生為甚欲，死為甚憎，所欲不得而所憎屢至，自古及今未嘗能有以此王天下、正諸侯者也。今大人慾王天下，正諸侯，將欲使意得乎天下，名成乎後世，故不察尚賢為政之本也。此聖人之厚行也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-9_p-8_s-1\",\n        \"mo-zi_ch-9_p-8_s-2\",\n        \"mo-zi_ch-9_p-8_s-3\",\n        \"mo-zi_ch-9_p-8_s-4\",\n        \"mo-zi_ch-9_p-8_s-5\",\n        \"mo-zi_ch-9_p-8_s-6\",\n        \"mo-zi_ch-9_p-8_s-7\",\n        \"mo-zi_ch-9_p-8_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今王公大人慾王天下，正諸侯，夫無德義將何以哉？他的推理說理將必挾震威彊。今王公大人將焉取挾震威彊哉？傾的人民的死啊。民生為甚欲，死為甚憎，所欲不得而且所憎屢至，自古及今未嘗能有以此王天下、正諸侯的人啊。今大人慾王天下，正諸侯，將欲使意得乎天下，概念名詞成乎後世，所以不察尚賢為政的本啊。此聖人的厚行啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚賢中〉。墨子學派以兼愛天下為宗，開篇「今王公大人慾王天下，正諸侯，夫無德義將何以哉」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「王」、「公」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今王公大人慾王天下正諸侯夫無德義將何以哉其說將必」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「其說將必挾震威彊」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子言曰：「今王公大人之君人民，主社稷，治國家，欲脩保而勿失，故不察尚賢為政之本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"何以知尚賢之為政本也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"曰自貴且智者，為政乎愚且賤者，則治；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"自愚且賤者，為政乎貴且智者，則亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"是以知尚賢之為政本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"故古者聖王甚尊尚賢而任使能，不黨父兄，不偏貴富，不嬖顏色，賢者舉而上之，富而貴之，以為官長；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"不肖者抑而廢之，貧而賤之以為徒役，是以民皆勸其賞，畏其罰，相率而為賢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"是以賢者眾，而不肖者寡，此謂進賢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"然後聖人聽其言，跡其行，察其所能，而慎予官，此謂事能。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"故可使治國者，使治國，可使長官者，使長官，可使治邑者，使治邑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-1_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"凡所使治國家，官府，邑里，此皆國之賢者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"賢者之治國者也，蚤朝晏退，聽獄治政，是以國家治而刑法正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"賢者之長官也，夜寢夙興，收斂關市、山林、澤梁之利，以實官府，是以官府實而財不散。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"賢者之治邑也，蚤出莫入，耕稼、樹藝、聚菽粟，是以菽粟多而民足乎食。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"故國家治則刑法正，官府實則萬民富。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"上有以絜為酒醴粢盛，以祭祀天鬼；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"外有以為皮幣，與四鄰諸侯交接，內有以食飢息勞，將養其萬民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"外有以懷天下之賢人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"是故上者天鬼富之，外者諸侯與之，內者萬民親之，賢人歸之，以此謀事則得，舉事則成，入守則固，出誅則彊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-2_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"故唯昔三代聖王堯、舜、禹、湯、文、武，之所以王天下正諸侯者，此亦其法已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"既曰若法，未知所以行之術，則事猶若未成，是以必為置三本。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"何謂三本？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"曰爵位不高則民不敬也，蓄祿不厚則民不信也，政令不斷則民不畏也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"故古聖王高予之爵，重予之祿，任之以事，斷予之令，夫豈為賢臣賜哉，欲其事之成也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"《詩》曰：『告女憂卹，誨女予爵，孰能執熱，鮮不用濯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"』則此語古者國君諸侯之不可以不執善，承嗣輔佐也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"譬之猶執熱之有濯也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"將休其手焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"古者聖王唯毋得賢人而使之，般爵以貴之，裂地以封之，終身不厭。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"賢人唯毋得明君而事之，竭四肢之力以任君之事，終身不倦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-3_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-3\",\n      \"order\": 11,\n      \"canonicalText\": \"若有美善則歸之上，是以美善在上，而所怨謗在下，寧樂在君，憂慼在臣，故古者聖王之為政若此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"今王公大人亦欲效人以尚賢使能為政，高予之爵，而祿不從也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"夫高爵而無祿，民不信也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"曰：『此非中實愛我也，假藉而用我也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"』夫假藉之民，將豈能親其上哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"故先王言曰：「貪於政者，不能分人以事；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"厚於貨者，不能分人以祿。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"」事則不與，祿則不分，請問天下之賢人將何自至乎王公大人之側哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"若苟賢者不至乎王公大人之側，則此不肖者在左右也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"不肖者在左右，則其所譽不當賢，而所毀不當暴，王公大人尊此以為政乎國家，則賞亦必不當賢，而罰亦必不當暴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"若苟賞不當賢而罰不當暴，則是為賢者不勸而為暴者不沮矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"是以入則不慈孝父母，出則不長弟鄉里，居處無節，出入無度，男女無別。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 12,\n      \"canonicalText\": \"使治官府則盜竊，守城則倍畔，君有難則不死，出亡則不從，使斷獄則不中，分財則不均，與謀事不得，舉事不成，入守不固，出誅不彊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 13,\n      \"canonicalText\": \"故雖昔者三代暴王桀紂幽厲之所以失措其國家，傾覆其社稷者，已此故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 14,\n      \"canonicalText\": \"何則？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-4_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-4\",\n      \"order\": 15,\n      \"canonicalText\": \"皆以明小物而不明大物也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"今王公大人，有一衣裳不能制也，必藉良工；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"有一牛羊不能殺也，必藉良宰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"故當若之二物者，王公大人皆知以尚賢使能為政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"逮至其國家之亂，社稷之危，則不知使能以治之，親戚則使之，無故富貴、面目佼好則使之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"夫無故富貴、面目佼好則使之，豈必智且有慧哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"若使之治國家，則此使不智慧者治國家也，國家之亂既可得而知已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"且夫王公大人有所愛其色而使，其心不察其知而與其愛。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"是故不能治百人者，使處乎千人之官，不能治千人者，使處乎萬人之官。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"此其故何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"曰處若官者爵高而祿厚，故愛其色而使之焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"夫不能治千人者，使處乎萬人之官，則此官什倍也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"夫治之法將日至者也，日以治之，日不什脩，知以治之，知不什益，而予官什倍，則此治一而棄其九矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"雖日夜相接以治若官，官猶若不治，此其故何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"則王公大人不明乎以尚賢使能為政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-5_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-5\",\n      \"order\": 15,\n      \"canonicalText\": \"故以尚賢使能為政而治者，若吾言之謂也，以下賢為政而亂者，若吾言之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"今王公大人中實將欲治其國家，欲脩保而勿失，胡不察尚賢為政之本也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"且以尚賢為政之本者，亦豈獨子墨子之言哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"此聖王之道，先王之書距年之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"傳曰：『求聖君哲人，以裨輔而身』，《湯誓》雲：『聿求元聖，與之戮力同心，以治天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"』則此言聖之不失以尚賢使能為政也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"故古者聖王唯能審以尚賢使能為政，無異物雜焉，天下皆得其利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"古者舜耕歷山，陶河瀕，漁雷澤，堯得之服澤之陽，舉以為天子，與接天下之政，治天下之民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"伊摯，有莘氏女之私臣，親為庖人，湯得之，舉以為己相，與接天下之政，治天下之民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"傅說被褐帶索。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"庸築乎傅巖，武丁得之，舉以為三公，與接天下之政，治天下之民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"此何故始賤卒而貴，始貧卒而富？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"則王公大人明乎以尚賢使能為政。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-6_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"是以民無飢而不得食，寒而不得衣，勞而不得息，亂而不得治者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"故古聖王以審以尚賢使能為政，而取法於天。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"雖天亦不辯貧富、貴賤、遠邇、親疏、賢者舉而尚之，不肖者抑而廢之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"然則富貴為賢，以得其賞者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"曰若昔者三代聖王堯、舜、禹、湯、文、武者是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"所以得其賞何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"曰其為政乎天下也，兼而愛之，從而利之，又率天下之萬民以尚尊天、事鬼、愛利萬民，是故天鬼賞之，立為天子，以為民父母，萬民從而譽之曰『聖王』，至今不已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"則此富貴為賢，以得其賞者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"然則富貴為暴，以得其罰者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"曰若昔者三代暴王桀、紂、幽、厲者是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 10,\n      \"canonicalText\": \"何以知其然也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 11,\n      \"canonicalText\": \"曰其為政乎天下也，兼而憎之，從而賊之，又率天下之民以詬天侮鬼，賊傲萬民，是故天鬼罰之，使身死而為刑戮，子孫離散，室家喪滅，絕無後嗣，萬民從而非之曰「暴王」，至今不已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 12,\n      \"canonicalText\": \"則此富貴為暴，而以得其罰者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 13,\n      \"canonicalText\": \"然則親而不善，以得其罰者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 14,\n      \"canonicalText\": \"曰若昔者伯鯀，帝之元子，廢帝之德庸，既乃刑之於羽之郊，乃熱照無有及也，帝亦不愛。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 15,\n      \"canonicalText\": \"則此親而不善以得其罰者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 16,\n      \"canonicalText\": \"然則天之所使能者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-17\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 17,\n      \"canonicalText\": \"曰若昔者禹、稷、皋陶是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-18\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 18,\n      \"canonicalText\": \"何以知其然也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-19\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 19,\n      \"canonicalText\": \"先王之書呂刑道之曰：『皇帝清問下民，有辭有苗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-20\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 20,\n      \"canonicalText\": \"曰群后之肆在下，明明不常，鰥寡不蓋，德威維威，德明維明。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-21\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 21,\n      \"canonicalText\": \"乃名三後，恤功於民，伯夷降典，哲民維刑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-22\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 22,\n      \"canonicalText\": \"禹平水土，主名山川。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-23\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 23,\n      \"canonicalText\": \"稷隆播種，農殖嘉穀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-24\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 24,\n      \"canonicalText\": \"三後成功，維假於民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-25\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 25,\n      \"canonicalText\": \"』則此言三聖人者，謹其言，慎其行，精其思慮，索天下之隱事遺利，以上事天，則天鄉其德，下施之萬民，萬民被其利，終身無已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-26\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 26,\n      \"canonicalText\": \"故先王之言曰：『此道也，大用之天下則不窕，小用之則不困，脩用之則萬民被其利，終身無已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-27\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 27,\n      \"canonicalText\": \"』周頌道之曰：『聖人之德，若天之高，若地之普，其有昭於天下也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-28\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 28,\n      \"canonicalText\": \"若地之固，若山之承，不坼不崩。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-29\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 29,\n      \"canonicalText\": \"若日之光，若月之明，與天地同常。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-30\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 30,\n      \"canonicalText\": \"』則此言聖人之德，章明博大，埴固，以脩久也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-7_s-31\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-7\",\n      \"order\": 31,\n      \"canonicalText\": \"故聖人之德蓋總乎天地者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"今王公大人慾王天下，正諸侯，夫無德義將何以哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"其說將必挾震威彊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"今王公大人將焉取挾震威彊哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"傾者民之死也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"民生為甚欲，死為甚憎，所欲不得而所憎屢至，自古及今未嘗能有以此王天下、正諸侯者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"今大人慾王天下，正諸侯，將欲使意得乎天下，名成乎後世，故不察尚賢為政之本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"此聖人之厚行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-9_p-8_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-9\",\n      \"passageId\": \"mo-zi_ch-9_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
